{
  "world_id": "wld_glasswater",
  "name": "The Glass Tide",
  "description": "At the edge of a bright, tidal lagoon, the city of Lume turns the daily rise and fall of water into power. Its gates feed canals, lift workshops, and keep gardens watered; its glassmakers shape the lagoon's pale sand into objects prized across the coast. Now a junior tide-warden has found that silt is closing the channels weeks early. To save the flow, the guilds must pause their most profitable season and decide who gets to guide the water. Lume is a hopeful solarpunk city built around patient craft, shared infrastructure, and the belief that repair can be a public art. Its most unusual instrument is a set of listening bells: tuned to the hollow chambers beneath the lagoon, they let wardens hear shifts in sediment before they show at the surface.",
  "locations": [
    {
      "id": "loc_lume_basin",
      "name": "Lume Basin",
      "description": "A sheltered lagoon whose daily tide turns submerged wheels and carries fresh water through the city. Its western shoals are gathering silt faster than the old maps predict."
    },
    {
      "id": "loc_sluice_steps",
      "name": "The Sluice Steps",
      "description": "A terraced gate complex where wardens balance the lagoon's flow among canals, gardens, and workshops. Listening bells hang beneath the walkways, sounding differently as the hidden channels clog."
    },
    {
      "id": "loc_sunward_glass",
      "name": "Sunward Glasshouse",
      "description": "A long-roofed cooperative of glass furnaces and solar mirrors. The workers rely on tidal wheels for grinding and ventilation, and their seasonal orders now compete with the basin's need for rest."
    },
    {
      "id": "loc_reedcommons",
      "name": "Reed Commons",
      "description": "A floating neighborhood of gardens, repair docks, and public meeting platforms. Residents track water quality with reed markers and keep records that challenge the guilds' official flow estimates."
    }
  ],
  "factions": [
    {
      "id": "fac_tidewardens",
      "name": "Tide-Wardens",
      "description": "Keepers of the gates and interpreters of the listening bells. They share authority by rota, but their warnings carry little weight when guild income is at stake.",
      "location_ids": [
        "loc_sluice_steps",
        "loc_lume_basin"
      ]
    },
    {
      "id": "fac_glass_cooperative",
      "name": "Sunward Glass Cooperative",
      "description": "A skilled makers' guild whose solar furnaces and tidal-powered tools support the city's celebrated glass season. Its members fear that a shutdown will cost apprentices their place and families their wages.",
      "location_ids": [
        "loc_sunward_glass"
      ]
    },
    {
      "id": "fac_reedcommons",
      "name": "Reed Commons Assembly",
      "description": "Gardeners, canal stewards, and repair crews who maintain shared waterways. They favor an early pause and want local observations recognized alongside guild accounts.",
      "location_ids": [
        "loc_reedcommons",
        "loc_lume_basin"
      ]
    },
    {
      "id": "fac_flowledger",
      "name": "The Flow Ledger",
      "description": "A civic circle of measurers and record-keepers that allocates water rights from seasonal tallies. It trusts long-running averages and is reluctant to revise its schedule without evidence all parties accept.",
      "location_ids": [
        "loc_sluice_steps",
        "loc_reedcommons"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_tidal_power",
      "statement": "The city's wheels and liftworks turn only when living water moves through them; stored power can bridge a short slack interval, not a missed tide.",
      "category": "physics"
    },
    {
      "id": "rul_silt_listening",
      "statement": "Changes in the buried channels alter the pitch of the listening bells before they become visible at the surface.",
      "category": "other"
    },
    {
      "id": "rul_solar_heat",
      "statement": "Craft heat comes from focused sunlight, and routine transport uses sails, current, muscle, or electric systems charged by sun and tide; combustion engines and fossil fuels have no place in the city's work.",
      "category": "technology"
    },
    {
      "id": "rul_shared_gates",
      "statement": "No guild may alter a main gate alone; a change requires a warden's reading and a public entry in the Flow Ledger.",
      "category": "social"
    },
    {
      "id": "rul_water_limits",
      "statement": "Fresh water drawn from the basin must be returned through planted reed beds before it can serve another neighborhood.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_first_gate",
      "name": "The First Turning",
      "description": "Builders shaped the first gates to follow the lagoon's natural pulse rather than hold it back. The arrangement powered shared mills and made water allocations a civic duty.",
      "era": "Founding years",
      "location_ids": [
        "loc_lume_basin",
        "loc_sluice_steps"
      ]
    },
    {
      "id": "evt_bell_compact",
      "name": "The Bell Compact",
      "description": "After a hidden shoal diverted a channel, wardens and residents hung tuned bells beneath the gates. Their readings became part of public water records, though the Flow Ledger later favored seasonal averages.",
      "era": "Three generations ago",
      "location_ids": [
        "loc_sluice_steps",
        "loc_reedcommons"
      ]
    },
    {
      "id": "evt_mirror_roofs",
      "name": "The Mirror Roofs",
      "description": "Glassmakers organized their furnaces beneath shared solar mirrors, replacing smoky heat with concentrated sunlight. Their craft prospered as tidal wheels took over grinding and ventilation.",
      "era": "Recent decades",
      "location_ids": [
        "loc_sunward_glass"
      ]
    },
    {
      "id": "evt_early_silting",
      "name": "The Early Silt Warning",
      "description": "A junior warden compared the bells' new low notes with reed markers and found the channels closing weeks ahead of the schedule. The discovery came just as seasonal glass orders reached their peak.",
      "era": "Present season",
      "location_ids": [
        "loc_lume_basin",
        "loc_sluice_steps",
        "loc_reedcommons"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_season_pause",
      "name": "The Season at Risk",
      "description": "The wardens and Reed Commons call for a halt to glass production so crews can clear the channels, while the glass cooperative fears lost wages and broken commitments. Any delay risks the lagoon's power; any pause places its costs unevenly on the people who depend on the workshops.",
      "faction_ids": [
        "fac_tidewardens",
        "fac_glass_cooperative",
        "fac_reedcommons"
      ]
    },
    {
      "id": "cnf_whose_evidence",
      "name": "The Measure of a Warning",
      "description": "The Flow Ledger's averages show time remains, but bell tones and reed markers point to a faster change. The dispute is not only about which figures are right, but who is trusted to define proof when the tide is shifting.",
      "faction_ids": [
        "fac_tidewardens",
        "fac_flowledger",
        "fac_reedcommons"
      ]
    }
  ]
}

