response.output:
{
  "world_id": "wld_mistfeather_isles",
  "name": "The Mistfeather Isles",
  "description": "Across a chain of rain-bright islands, sword schools guard old paths through reed marsh, cedar ridges, and tidal stone. Their rivalries are measured in poems, debts, and formally witnessed bouts; a challenge must be declared before both sides, and an ambush brings disgrace upon the aggressor's whole school. Now the last crane rookeries are shrinking as clan borders close around the nesting marshes. A disowned sword-student carries her late master's tally-stick from one sect to the next, seeking to summon a peace moot before the birds abandon the islands. The stick bears notches that echo the rookeries' yearly return, and its final mark has appeared before its season.",
  "locations": [
    {
      "id": "loc_saltveil_harbor",
      "name": "Saltveil Harbor",
      "description": "A wharf-town of pale stone and hanging nets, where tide pilots keep neutral guest rooms for travelers bearing school tokens. Three currents meet beneath its piers, making it the customary place to announce a formal challenge or a peace moot."
    },
    {
      "id": "loc_willowglass_marsh",
      "name": "Willowglass Marsh",
      "description": "A broad, mirror-still wetland threaded with reed causeways and floating gardens. The last great crane rookery nests in its sheltered pools, while boundary stakes creep closer each spring."
    },
    {
      "id": "loc_emberpine_ridge",
      "name": "Emberpine Ridge",
      "description": "A steep spine of red-barked pines and wind-cut steps, home to a school that trains its students to read an opponent's balance from the sway of needles. At dusk, the ridge casts a long shadow across the marsh."
    },
    {
      "id": "loc_moonwell_cloister",
      "name": "Moonwell Cloister",
      "description": "A quiet sanctuary built around a freshwater spring that reflects the moon even at noon. Its keepers preserve old tallies and witness disputes, but their archive holds a second version of the late master's final count."
    }
  ],
  "factions": [
    {
      "id": "fac_reed_lantern_school",
      "name": "Reed Lantern School",
      "description": "Marsh guardians and elegant spear-and-sword practitioners who believe the rookery is shared ground. Their patience is wearing thin as neighboring clans move markers into the nesting pools.",
      "location_ids": [
        "loc_willowglass_marsh"
      ]
    },
    {
      "id": "fac_emberpine_sword_hall",
      "name": "Emberpine Sword Hall",
      "description": "A proud ridge school that treats declared duels as public law. Its elders claim the high paths and insist that marsh access must be earned through a settlement of old boundary debts.",
      "location_ids": [
        "loc_emberpine_ridge"
      ]
    },
    {
      "id": "fac_tideglass_compact",
      "name": "Tideglass Compact",
      "description": "Harbor clans bound by trade oaths and a shared fleet of shallow-draft boats. They favor a negotiated moot, yet profit from carrying supplies to both sides and fear losing that leverage.",
      "location_ids": [
        "loc_saltveil_harbor"
      ]
    },
    {
      "id": "fac_moonwell_witnesses",
      "name": "Moonwell Witnesses",
      "description": "Cloister archivists who certify tallies, challenges, and truces. Their vow forbids them from choosing a side, though a concealed duplicate record may force them to break silence.",
      "location_ids": [
        "loc_moonwell_cloister"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_declared_challenge",
      "statement": "A duel is legitimate only after a formal challenge is spoken before witnesses; ambush is forbidden and brings lasting disgrace upon the aggressor's school.",
      "category": "social"
    },
    {
      "id": "rul_tally_echo",
      "statement": "A tally-stick cut from moon ash can record an oath in its grain; when the oath is threatened, one notch darkens, though the stick cannot reveal who broke faith.",
      "category": "metaphysics"
    },
    {
      "id": "rul_rookery_return",
      "statement": "The cranes return to the same sheltered pools each year unless nesting waters are disturbed or their feeding shallows are claimed.",
      "category": "other"
    },
    {
      "id": "rul_school_guest_right",
      "statement": "A traveler carrying a recognized school token may ask for one night of shelter at a neutral harbor or cloister, even during a feud.",
      "category": "social"
    },
    {
      "id": "rul_blade_and_breath",
      "statement": "Sword forms depend on breath, footing, and practiced balance; no art grants strength without fatigue or makes a wounded body invulnerable.",
      "category": "physics"
    }
  ],
  "history": [
    {
      "id": "evt_first_rookery_oath",
      "name": "The First Rookery Oath",
      "description": "The island schools ended an earlier border war by promising to leave the nesting pools unclaimed. A moon-ash tally recorded the agreement, and its notches became the measure of each spring's return.",
      "era": "Founding era",
      "location_ids": [
        "loc_willowglass_marsh",
        "loc_moonwell_cloister"
      ]
    },
    {
      "id": "evt_three_current_duel",
      "name": "Duel at Three Currents",
      "description": "A harbor dispute was settled by a declared bout on the pier, witnessed by all three clans. The victor surrendered the prize to the rookery instead, establishing Saltveil as a place where a challenge could end without a land seizure.",
      "era": "A generation ago",
      "location_ids": [
        "loc_saltveil_harbor"
      ]
    },
    {
      "id": "evt_masters_last_tally",
      "name": "The Master's Last Tally",
      "description": "The late master carried a tally-stick between the schools and was disowned by his former student after refusing to name which clan had first crossed the marsh boundary. His final count disagrees with the cloister's hidden duplicate.",
      "era": "Recent years",
      "location_ids": [
        "loc_emberpine_ridge",
        "loc_moonwell_cloister"
      ]
    },
    {
      "id": "evt_early_black_notch",
      "name": "The Early Black Notch",
