response.output:
{
  "world_id": "wld_sunside",
  "name": "Sunside Yard",
  "description": "Inside Mercury's orbit, Sunside is a solar-sail shipyard where every transfer window is a wager against orbital mechanics and every watt has an owner. Salvage rigger Mara Venn finds a hull listed as scrapped still drawing power through its deployed sail. The yard's charter auditors are inbound; unless she can establish the hull's identity and prove its live draw before they arrive, the evidence may be dismantled as salvage—or sealed as a breach of charter. The yard's oddest instrument is its shadow ledger: a bank of calibrated mirrors that records a ship's changing silhouette against the Sun, giving disputes a physical trace no revised manifest can erase. Work is dangerous, records are leverage, and light itself leaves a paper trail.",
  "locations": [
    {
      "id": "loc_helion_yard",
      "name": "Helion Yard",
      "description": "A rotating work hub on a heliocentric orbit inside Mercury's, built from truss, pressure drums, and sun-facing radiator wings. Salvage crews clamp incoming hulls here and schedule every maneuver around limited propellant and changing trajectories."
    },
    {
      "id": "loc_shade_spine",
      "name": "Shade Spine",
      "description": "A long radiator and crew refuge kept in the yard's engineered shadow. Riggers stage tools and suit up here, where a stray sunward reflection can ruin delicate thermal work."
    },
    {
      "id": "loc_ledger_hall",
      "name": "Ledger Hall",
      "description": "The charter office, evidence vault, and mirror-backed shadow ledger occupy one shielded module. Its instruments compare recorded light profiles with hull filings; disputed readings are difficult to alter without leaving a detectable gap."
    },
    {
      "id": "loc_wreck_cradle",
      "name": "Wreck Cradle",
      "description": "An open truss berth for condemned ships, reached by slow tug from the yard. One supposedly scrapped hull remains here, its furled sail showing a faint, regular power draw that should have ended when its registry was closed."
    }
  ],
  "factions": [
    {
      "id": "fac_yard_union",
      "name": "Cradle Hands",
      "description": "The riggers' mutual union controls work rotations and safety procedures. Its members want the live hull investigated, but fear that a charter violation could cost everyone their berth and wages.",
      "location_ids": [
        "loc_helion_yard",
        "loc_shade_spine",
        "loc_wreck_cradle"
      ]
    },
    {
      "id": "fac_charter_office",
      "name": "Solar Charter Office",
      "description": "The yard's licensing authority sends auditors to verify ownership, power accounting, and disposal records. It insists that a closed scrap entry is binding unless evidence meets its strict chain-of-custody rules.",
      "location_ids": [
        "loc_ledger_hall"
      ]
    },
    {
      "id": "fac_salvage_consortium",
      "name": "Brightline Salvage",
      "description": "The consortium finances the yard and claims title to abandoned material. It wants the anomalous hull treated as a clerical remnant before the auditors can assign it a value or reopen its ownership.",
      "location_ids": [
        "loc_helion_yard",
        "loc_wreck_cradle"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_orbit",
      "statement": "Ships and yard modules travel on trajectories governed by gravity; changing an orbit takes time, propellant, or a deliberately arranged sail maneuver.",
      "category": "physics"
    },
    {
      "id": "rul_signal_delay",
      "statement": "Messages move no faster than light, so distant parties cannot coordinate in real time and arrival times matter.",
      "category": "physics"
    },
    {
      "id": "rul_no_instant_transit",
      "statement": "No device can move a person or object instantly between locations; physical travel requires a traversable route and elapsed time.",
      "category": "technology"
    },
    {
      "id": "rul_sail_power",
      "statement": "A solar sail can provide thrust from sunlight, while its conductive layers can also induce measurable current when exposed to the yard's operating fields.",
      "category": "technology"
    },
    {
      "id": "rul_shadow_record",
      "statement": "The charter recognizes calibrated shadow-ledger measurements as evidence only when the mirror sequence, instrument clock, and custody record remain continuous.",
      "category": "social"
    },
    {
      "id": "rul_salvage_title",
      "statement": "A scrap entry transfers a hull to the salvage claimant only after its registered power source is isolated and the disposal record is certified.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_shadow_ledger",
      "name": "The Mirror Accord",
      "description": "After a disputed disposal erased a worker crew's claim, yard riggers and charter clerks established the shadow ledger. Its mirrored record became the yard's accepted independent check on hull identity and exposure.",
      "era": "Three decades before the present",
      "location_ids": [
        "loc_ledger_hall",
        "loc_helion_yard"
      ]
    },
    {
      "id": "evt_hull_scrapped",
      "name": "Closure of the Missing Hull",
      "description": "A consortium manifest marked an unidentified vessel as scrapped after its power isolation certificate was filed. The physical hull was placed in the Wreck Cradle, but its sail was never entered in the disposal inventory.",
      "era": "Eleven days before the present",
      "location_ids": [
        "loc_ledger_hall",
        "loc_wreck_cradle"
      ]
    },
    {
      "id": "evt_power_anomaly",
      "name": "The Recurring Draw",
      "description": "A rigger noticed a small, periodic current in the cradle's service bus. The signal persisted through a scheduled yard load test, suggesting the supposedly dead hull was still coupled to a live source.",
      "era": "Two days before the present",
      "location_ids": [
        "loc_wreck_cradle",
        "loc_helion_yard"
      ]
    },
    {
      "id": "evt_auditors_inbound",
      "name": "Audit Notice",
      "description": "The Charter Office dispatched auditors on a slow, preplanned transfer. Their arrival is public knowledge, but their exact findings cannot be known until they reach the yard and inspect the evidence.",
      "era": "Present",
      "location_ids": [
        "loc_ledger_hall"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_live_hull",
      "name": "The Hull That Still Draws",
      "description": "The Cradle Hands need time to trace the current and preserve the sail's light profile; Brightline Salvage wants the hull dismantled before the auditors arrive. A rushed cut could destroy the only evidence, while delay may look like concealment.",
      "faction_ids": [
        "fac_yard_union",
        "fac_salvage_consortium"
      ]
    },
    {
      "id": "cnf_charter_verdict",
      "name": "Proof Before Arrival",
      "description": "The Charter Office will accept a challenge only with continuous custody and corroborating measurements. The union suspects the filed isolation record is false, while the consortium argues that any unapproved test breaks custody and forfeits the claim.",
      "faction_ids": [
        "fac_yard_union",
        "fac_charter_office",
        "fac_salvage_consortium"
      ]
    }
  ]
}

