response.output:
{
  "world_id": "wld_rainrememberedvalley",
  "name": "The Remembering Vale",
  "description": "In a valley still healing from a long collapse, rain carries the faint taste of whatever seed was planted nearby. A seed-keeper's caravan must cross three recovering towns before the last frost, carrying grain stock and trying to mend the feud that divided the old seedway routes. Communities rely on salvaged hand-tools, shared labor, and weather-worn stores; nothing powered remains. The journey follows a chain of four settlements where each harvest depends on trust as much as soil. Wistful memories of abundance linger in the rain, but careful planting and hard-won cooperation offer a hopeful future.",
  "locations": [
    {
      "id": "loc_morrowford",
      "name": "Morrowford",
      "description": "The caravan's starting settlement, built around a shallow river crossing and a communal seed loft. Its elders have entrusted the grain stock to the seed-keeper, though the loft's tally marks do not agree."
    },
    {
      "id": "loc_siltmarket",
      "name": "Siltmarket",
      "description": "A riverside town whose gardens grow in layered flood mud. Traders exchange hand-forged tools and seed in a roofed market, where old route claims still sour every bargain."
    },
    {
      "id": "loc_lanternridge",
      "name": "Lanternridge",
      "description": "A steep hillside settlement with terrace plots and rain-catching stone bowls. At dusk, residents set small lamps along the terraces to signal which paths are safe after frost."
    },
    {
      "id": "loc_wintermere",
      "name": "Wintermere",
      "description": "The northernmost town, clustered beside a cold lake and a communal grain house. Its fields need seed before the last frost, but its people distrust any caravan carrying Morrowford's mark."
    }
  ],
  "factions": [
    {
      "id": "fac_loftkeepers",
      "name": "The Loftkeepers",
      "description": "Morrowford's custodians of shared grain and planting records. They believe stores must be distributed by need, yet their faded ledgers leave room for accusations of favoritism.",
      "location_ids": [
        "loc_morrowford"
      ]
    },
    {
      "id": "fac_rainwardens",
      "name": "The Rainwardens",
      "description": "A loose fellowship of growers who record the taste of rain and match it to nearby plantings. Their observations guide planting, but outsiders sometimes mistake their careful warnings for superstition.",
      "location_ids": [
        "loc_siltmarket",
        "loc_lanternridge"
      ]
    },
    {
      "id": "fac_northcompact",
      "name": "The North Compact",
      "description": "Wintermere families bound by a promise to guard their remaining grain until the town can replant. They disagree over whether old route debts should be settled before aid is accepted.",
      "location_ids": [
        "loc_wintermere"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_raintrace",
      "statement": "Rain carries a faint trace of the most common seed planted within its watershed, but the trace fades after the water leaves the valley.",
      "category": "metaphysics"
    },
    {
      "id": "rul_frostline",
      "statement": "Once the last hard frost passes, grain sown in the valley will not mature before the next cold season.",
      "category": "physics"
    },
    {
      "id": "rul_handwork",
      "statement": "All useful tools are worked by hand or animal strength; no powered machines remain in working order.",
      "category": "technology"
    },
    {
      "id": "rul_seedright",
      "statement": "A settlement may reserve grain for planting, but no family may claim a seed lot without recording its source and intended plot.",
      "category": "social"
    },
    {
      "id": "rul_routewitness",
      "statement": "A route agreement is considered binding only when witnessed by people from both settlements it connects.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_splitway",
      "name": "The Split Seedway",
      "description": "A disputed grain tally led Morrowford and Wintermere to accuse one another of withholding seed. Their shared route was divided, and the middle towns inherited competing promises.",
      "era": "Years of the Broken Ledger",
      "location_ids": [
        "loc_morrowford",
        "loc_siltmarket",
        "loc_wintermere"
      ]
    },
    {
      "id": "evt_firstrain",
      "name": "The First Tasting",
      "description": "After a season of failed guesses, growers noticed that rainwater near a field carried a trace of its planted grain. The Rainwardens began keeping watershed records, turning a curious sign into practical planting knowledge.",
      "era": "The Early Recovery",
      "location_ids": [
        "loc_siltmarket",
        "loc_lanternridge"
      ]
    },
    {
      "id": "evt_lampromise",
      "name": "The Terrace Lamps",
      "description": "Lanternridge's growers began lighting terrace paths to guide late harvest workers through fog. The custom became a public signal that neighbors would share labor even when their stores ran thin.",
      "era": "The Years of Repair",
      "location_ids": [
        "loc_lanternridge"
      ]
    },
    {
      "id": "evt_lasttally",
      "name": "The Uneven Tally",
      "description": "A new comparison of old loft marks suggests the feud began with a counting error rather than theft. The evidence has not yet reached Wintermere, where the last grain reserve awaits a decision.",
      "era": "The Present Thaw",
      "location_ids": [
        "loc_morrowford",
        "loc_wintermere"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_routeclaim",
      "name": "The Divided Route",
      "description": "The Loftkeepers need the North Compact to accept grain before the frost, while the Compact insists that route debts be acknowledged first. The caravan can carry enough to help, but not enough to satisfy every claim without reopening the old dispute.",
      "faction_ids": [
        "fac_loftkeepers",
        "fac_northcompact"
      ]
    },
    {
      "id": "cnf_rainrecord",
      "name": "What the Rain Can Prove",
      "description": "The Rainwardens' watershed notes may explain which seed reached each town, yet their evidence is partial and easy to challenge. Revealing it could reconcile the route or give each side a new reason to distrust the others.",
      "faction_ids": [
        "fac_rainwardens",
        "fac_loftkeepers",
        "fac_northcompact"
      ]
    }
  ]
}

