      "location_ids": [
        "loc_siltmarket",
        "loc_lanternridge"
      ]
    },
    {
      "id": "evt_lampromise",
      "name": "The Terrace Lamps",
      "description": "Lanternridge's growers began lighting terrace paths to guide late harvest workers through fog. The custom became a public signal that neighbors would share labor even when their stores ran thin.",
      "era": "The Years of Repair",
      "location_ids": [
        "loc_lanternridge"
      ]
    },
    {
      "id": "evt_lasttally",
      "name": "The Uneven Tally",
      "description": "A new comparison of old loft marks suggests the feud began with a counting error rather than theft. The evidence has not yet reached Wintermere, where the last grain reserve awaits a decision.",
      "era": "The Present Thaw",
      "location_ids": [
        "loc_morrowford",
        "loc_wintermere"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_routeclaim",
      "name": "The Divided Route",
      "description": "The Loftkeepers need the North Compact to accept grain before the frost, while the Compact insists that route debts be acknowledged first. The caravan can carry enough to help, but not enough to satisfy every claim without reopening the old dispute.",
      "faction_ids": [
        "fac_loftkeepers",
        "fac_northcompact"
      ]
    },
    {
      "id": "cnf_rainrecord",
      "name": "What the Rain Can Prove",
      "description": "The Rainwardens' watershed notes may explain which seed reached each town, yet their evidence is partial and easy to challenge. Revealing it could reconcile the route or give each side a new reason to distrust the others.",
      "faction_ids": [
        "fac_rainwardens",
        "fac_loftkeepers",
        "fac_northcompact"
      ]
    }
  ]
}

