      "description": "A narrow causeway over a soundless gulf, crossed by account runners carrying sealed amendments between offices. Spoken words fade here; written ones remain legible."
    },
    {
      "id": "loc_final_scales",
      "name": "The Final Scales",
      "description": "A vast weighing hall at the end of the process. Its brass pans measure the shape of an account, while the unrecorded parts of a life gather like shadows beneath them."
    }
  ],
  "factions": [
    {
      "id": "fac_first_entry",
      "name": "First Entry Clerks",
      "description": "Keepers of the Wick Archive who believe an account should preserve what a soul did, including the inconvenient parts no one thought to write down.",
      "location_ids": [
        "loc_wick_archive",
        "loc_silt_gate"
      ]
    },
    {
      "id": "fac_order_of_columns",
      "name": "Order of the Proper Column",
      "description": "Senior tally officials who defend stable classifications as the only barrier against endless appeals. Their procedures are impeccable, and their exceptions are carefully concealed.",
      "location_ids": [
        "loc_tally_court",
        "loc_final_scales"
      ]
    },
    {
      "id": "fac_wayrunners",
      "name": "The Wayrunners",
      "description": "Messengers who carry amendments across the Hush Bridge. They tie a black thread around any packet that has been altered in transit, a custom the offices officially dismiss and quietly fear.",
      "location_ids": [
        "loc_hush_bridge",
        "loc_tally_court"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_account_only",
      "statement": "The dead cannot return to mortal life; only their accounts may be amended, transferred, or reclassified.",
      "category": "metaphysics"
    },
    {
      "id": "rul_weighted_entry",
      "statement": "The Final Scales weigh the account presented to them, not an unrecorded intention or a clerk's private opinion.",
      "category": "metaphysics"
    },
    {
      "id": "rul_sealed_amendment",
      "statement": "A correction becomes binding only when its original entry and every later transfer are joined in one sealed chain.",
      "category": "social"
    },
    {
      "id": "rul_candle_witness",
      "statement": "In the Wick Archive, a candle flame leans toward a deliberate omission, but it cannot identify who made it.",
      "category": "other"
    },
    {
      "id": "rul_written_crossing",
      "statement": "Across the Hush Bridge, spoken words vanish while written words endure, so testimony must be carried on paper to survive the crossing.",
      "category": "physics"
    }
  ],
  "history": [
    {
      "id": "evt_first_columns",
      "name": "The First Columns",
      "description": "The earliest clerks divided accounts into columns to make the growing queues manageable. The divisions endured long after anyone remembered why those particular headings had been chosen.",
      "era": "Founding Reckoning",
      "location_ids": [
        "loc_wick_archive",
        "loc_tally_court"
      ]
    },
    {
      "id": "evt_bridge_silence",
      "name": "The Bridge Fell Silent",
      "description": "After a disputed amendment was lost to rumor, the Hush Bridge became a place where only written testimony could be trusted. Wayrunners adopted the black thread as a warning against tampering.",
      "era": "Era of the Quiet Crossing",
      "location_ids": [
        "loc_hush_bridge"
      ]
    },
    {
      "id": "evt_unfinished_pan",
      "name": "The Unfinished Weighing",
      "description": "A soul once reached the Final Scales with two conflicting accounts. The hearing was suspended rather than choose between them, and the empty pan has remained reserved for unresolved cases ever since.",
      "era": "The Suspended Year",
      "location_ids": [
        "loc_final_scales",
        "loc_tally_court"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_wrong_column",
      "name": "The Wrong Column",
      "description": "A junior scribe's discovery threatens to expose that a mortal soul was classified under a heading that changes the weight of its account. Correcting it may require proof from offices that benefit from leaving it untouched.",
      "faction_ids": [
        "fac_first_entry",
        "fac_order_of_columns",
        "fac_wayrunners"
      ]
    },
    {
      "id": "cnf_chain_of_custody",
      "name": "The Missing Link",
      "description": "The amendment's sealed chain has a gap between the archive and the court. The Order demands exact procedure, the First Entry Clerks suspect a deliberate omission, and the Wayrunners know a packet crossed the bridge under a black thread.",
      "faction_ids": [
        "fac_first_entry",
        "fac_order_of_columns",
        "fac_wayrunners"
      ]
    }
  ]
}

