response.output:
{
  "world_id": "wld_ninth_bell",
  "name": "The Drowned Reach",
  "description": "The Drowned Reach is an estuary city of leaning brick parishes, salt-stained foundries, and narrow canals where fog arrives like a tide with its own schedule. Gas lamps and oil lanterns mark the streets; when the mist swallows their glow, the city listens for its storm-bells. Their notes once warned of flood and gale, but now an impossible pattern rings from towers whose founders swear they never cast it. An apprentice who recognizes the rhythm faces a parish order to silence every bell before the next fog. In this eerie gaslamp world, a sound can be both a civic safeguard and a secret no one wants heard.",
  "locations": [
    {
      "id": "loc_candlehook",
      "name": "Candlehook Foundry",
      "description": "A soot-blackened bellworks crouched above the tidal flats. Apprentices cast bronze by furnace glow, and old molds hang from the rafters with their maker's marks filed away."
    },
    {
      "id": "loc_nine_parishes",
      "name": "The Nine Parishes",
      "description": "A close-packed quarter of chapels and crooked lanes. Its nine storm-bells share no tower, yet their ropes are said to twitch together when the estuary fog thickens."
    },
    {
      "id": "loc_siltmarket",
      "name": "Siltmarket",
      "description": "A floating market lashed to the canal banks, where fishmongers trade beneath oil lamps and ferrymen sell rumors along with passage."
    },
    {
      "id": "loc_drowned_archive",
      "name": "The Drowned Archive",
      "description": "A sealed record house below the old quay. At low tide, its upper stair appears, leading to parish ledgers and casting plans kept in waxed cabinets."
    },
    {
      "id": "loc_blackwater_lighthouse",
      "name": "Blackwater Light",
      "description": "A squat harbor beacon whose hooded oil flame is tended through every gale. From its gallery, the bell towers seem to stand in a single line across the fog."
    }
  ],
  "factions": [
    {
      "id": "fac_parish_wardens",
      "name": "The Parish Wardens",
      "description": "Clerks, beadles, and tower keepers who control the storm-bells and insist the unapproved pattern is a danger to public order. They have ordered the bells silenced until the next fog passes.",
      "location_ids": [
        "loc_nine_parishes",
        "loc_blackwater_lighthouse"
      ]
    },
    {
      "id": "fac_candlehook_guild",
      "name": "Candlehook Founders' Guild",
      "description": "A proud craft guild guarding its casting methods and marks. Its masters fear that the impossible ringing will expose a hidden mold or a long-buried breach of their vows.",
      "location_ids": [
        "loc_candlehook"
      ]
    },
    {
      "id": "fac_lowtide_listeners",
      "name": "The Lowtide Listeners",
      "description": "Ferrymen and market folk who chart the bells by ear and keep unofficial records on scraps of sailcloth. They believe the strange pattern points toward something beneath the old quay.",
      "location_ids": [
        "loc_siltmarket",
        "loc_drowned_archive"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_fog_bearing",
      "statement": "Storm-bells carry across the estuary fog farther than ordinary speech, even when their towers cannot be seen.",
      "category": "metaphysics"
    },
    {
      "id": "rul_tide_timing",
      "statement": "The city's floodgates are opened and closed by tide tables and bell signals; no single parish may alter the sequence alone.",
      "category": "social"
    },
    {
      "id": "rul_forge_light",
      "statement": "Foundries burn coal, while streets and homes are lit by gas or oil flame.",
      "category": "technology"
    },
    {
      "id": "rul_ninth_interval",
      "statement": "A ninth interval sometimes sounds between the established storm-bell notes, though no surviving casting plan records a bell tuned to it.",
      "category": "metaphysics"
    },
    {
      "id": "rul_silence_oath",
      "statement": "By parish law, only the wardens may order a storm-bell muted, and any such order must be read aloud at the tower door.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_quay_foundation",
      "name": "The Quay That Sank",
      "description": "The first stone quay settled into the mud during a spring tide. The city rebuilt above it, leaving chambers and older streets sealed beneath the harbor edge.",
      "era": "Founding years",
      "location_ids": [
        "loc_drowned_archive",
        "loc_blackwater_lighthouse"
      ]
    },
    {
      "id": "evt_storm_bell_compact",
      "name": "The Storm-Bell Compact",
      "description": "After a deadly surge, the parishes agreed on a shared sequence of warning notes and gave the wardens authority over the tower ropes.",
      "era": "Compact era",
      "location_ids": [
        "loc_nine_parishes"
      ]
    },
    {
      "id": "evt_candlehook_vow",
      "name": "The Founders' Vow",
      "description": "Candlehook's masters pledged to preserve every casting plan and mark each bell with its maker's sign. Some later ledgers carry blank spaces where those marks should be.",
      "era": "Guild years",
      "location_ids": [
        "loc_candlehook",
        "loc_drowned_archive"
      ]
    },
    {
      "id": "evt_first_ninth",
      "name": "The Unlisted Note",
      "description": "During a fog-bound gale, witnesses heard a ninth interval between the warning notes. The wardens called it a mistaken echo, though a ferryman's chart places its source beneath the old quay.",
      "era": "Recent years",
      "location_ids": [
        "loc_siltmarket",
        "loc_nine_parishes"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_silence_or_warning",
      "name": "Silence Before Fog",
      "description": "The wardens want every tower quiet before the next fog, while the Lowtide Listeners argue the pattern may be the only warning of a coming surge. Defiance could save lives—or bring the parishes down on those who ring.",
      "faction_ids": [
        "fac_parish_wardens",
        "fac_lowtide_listeners"
      ]
