response.output:
{
  "world_id": "wld_leapseasonlanes",
  "name": "The Lanes Between Seasons",
  "description": "Once every leap-season, a travelling fair unfolds along the old road to Bellweather, its stalls tucked into lanes that seem longer inside than out. Mira Fen, a hedge-witch who brews teas for every kind of homesickness, follows its lanterns in hopes of reclaiming the ninth stall her family lost generations ago. The fair's paths are governed by careful customs: promises carry weight, prices may be paid in stories or service, and every dispute must find its answer in a bargain, contest, or exchange. As the lanes prepare to fold and wander onward, Mira must discover what her family truly traded away—and whether the stall can belong to someone who offers something new.",
  "locations": [
    {
      "id": "loc_bellweather",
      "name": "Bellweather Green",
      "description": "A meadow at the edge of a sleepy village where the fair's first striped awnings appear. Each leap-season, a different old milestone serves as its gate, and villagers leave cups of plain tea there to welcome the arriving lanes."
    },
    {
      "id": "loc_kettle_lane",
      "name": "Kettle Lane",
      "description": "A winding passage of tea shops, copper kettles, and tiny gardens growing in cracked paving stones. The ninth stall once stood here, though its place now shifts a few paces whenever someone tells an untrue story about its history."
    },
    {
      "id": "loc_mirror_exchange",
      "name": "The Mirror Exchange",
      "description": "A covered market whose silvered bowls show not faces but the wares a visitor could offer. Traders make their most delicate bargains here, with witnesses chosen from among the exchange's patient, tea-drinking cats."
    },
    {
      "id": "loc_foldstage",
      "name": "Foldstage Court",
      "description": "A circular courtyard of hinged wooden platforms where the fair settles claims through riddles, recipe trials, and feats of careful craft. At closing time, the platforms tuck together into a traveling chest, carrying the court to the next season's road."
    }
  ],
  "factions": [
    {
      "id": "fac_lane_keepers",
      "name": "The Lane-Keepers",
      "description": "A fellowship of fair stewards who remember where each lane has wandered and keep its customs legible to newcomers. They will not decide who deserves a stall, but they insist every claim be settled before the lanes fold.",
      "location_ids": [
        "loc_bellweather",
        "loc_foldstage"
      ]
    },
    {
      "id": "fac_copper_circle",
      "name": "The Copper Circle",
      "description": "Tea merchants who share kettles, recipes, and customers along Kettle Lane. They want the ninth stall filled, but disagree over whether Mira should inherit it or earn it by bringing a new blend to the fair.",
      "location_ids": [
        "loc_kettle_lane",
        "loc_mirror_exchange"
      ]
    },
    {
      "id": "fac_ninth_claimants",
      "name": "The Ninth Claimants",
      "description": "A small group of stallholders whose families each recall a different promise tied to the empty ninth place. They are not rivals by nature; each fears that accepting another family's version of the past will cost their own people something they cannot replace.",
      "location_ids": [
        "loc_kettle_lane",
        "loc_foldstage"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_leap_arrival",
      "statement": "The fair can enter the ordinary world only during leap-season, and it must leave before that season ends.",
      "category": "metaphysics"
    },
    {
      "id": "rul_lane_memory",
      "statement": "A lane remembers every promise spoken within it, though its signs may rearrange to point toward the promise most in need of keeping.",
      "category": "metaphysics"
    },
    {
      "id": "rul_exchange",
      "statement": "A fair bargain is binding only when each side names what they give and accepts what they receive.",
      "category": "social"
    },
    {
      "id": "rul_settlement",
      "statement": "Claims and disputes at the fair are settled through bargains, contests, or trade.",
      "category": "social"
    },
    {
      "id": "rul_brewcraft",
      "statement": "Hedge-witch teas can lend a drinker a memory's scent or warmth, but they cannot change what happened.",
      "category": "metaphysics"
    }
  ],
  "history": [
    {
      "id": "evt_first_ninth",
      "name": "The Ninth Kettle Promise",
      "description": "Long ago, Mira's ancestor traded the family's place at the ninth stall for a promise that the stall would remain open to any brewer who had nowhere else to sell. The promise was remembered, but its exact terms were never written down.",
      "era": "The First Wandering",
      "location_ids": [
        "loc_kettle_lane",
        "loc_mirror_exchange"
      ]
    },
    {
      "id": "evt_stall_folding",
      "name": "The Stall That Folded Away",
      "description": "A later keeper mistook the promise for a permanent family claim and tried to reserve the ninth stall across seasons. The lane folded the empty stall into its traveling chest, leaving several families with different accounts of what had been agreed.",
      "era": "The Long Interval",
      "location_ids": [
        "loc_kettle_lane",
        "loc_foldstage"
      ]
    },
    {
      "id": "evt_new_gate",
      "name": "The Milestone Welcome",
      "description": "Bellweather's villagers began leaving tea at the fair's changing gate. The custom helped newcomers find the lanes and gave the Lane-Keepers a reliable place to hear fresh claims before the fair moved on.",
      "era": "Recent leap-seasons",
      "location_ids": [
        "loc_bellweather"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_ninth_stall_claim",
      "name": "Who May Pour at Nine?",
      "description": "Mira wants the ninth stall restored to her family, while the Ninth Claimants believe the old promise made it a shared place for any brewer in need. The Copper Circle proposes a tasting contest whose winner chooses the next keeper, but Mira suspects the family recipe hidden in her tea tin could reveal a fairer bargain before closing night.",
      "faction_ids": [
        "fac_copper_circle",
        "fac_ninth_claimants",
        "fac_lane_keepers"
      ]
    }
  ]
}

