{
  "world_id": "wld_ice_and_coin",
  "name": "The Comet Bazaar",
  "description": "A wandering market clings to the dark spine of a captured comet, where caravan ships furl their patched sails and trade by lanternlight against a sky full of stars. Its narrow passages, tether bridges, and caverns of old ice make every bargain a public spectacle and every secret a perilous thing to carry. A guild factotum must arbitrate the theft of a sealed star-map before the comet swings sunward: when its ice vents flare into a perihelion burn, the market’s fleet will scatter along competing escape routes. Here, contracts are theatrical, justice is a matter of witnesses, and a clever ruling can save a ship—or strand a whole family among the fragments.",
  "locations": [
    {
      "id": "loc_crown_dock",
      "name": "Crown Dock",
      "description": "The market’s busy outer harbor, where ships moor by braided tethers and canvas sails hang like bright awnings. Dock crews barter for rigging, water, and safe passage while tracking the comet’s changing spin."
    },
    {
      "id": "loc_blue_vault",
      "name": "The Blue Vault",
      "description": "A natural chamber in the comet’s buried ice, used by the guild to hold sealed cargo and disputed property. Its walls preserve every scratch and handprint, but rumors say the old ice sometimes records sounds from ships that departed generations ago."
    },
    {
      "id": "loc_coin_choir",
      "name": "Coin Choir",
      "description": "A steep bazaar of hanging stalls whose merchants ring their wares with tiny metal chimes. Each stall’s distinct rhythm marks its owner’s standing; during a dispute, a missing note can matter as much as a missing witness."
    },
    {
      "id": "loc_knotcourt",
      "name": "Knotcourt",
      "description": "A circular tribunal lashed around a low-gravity cavern, with witness platforms suspended on independent tethers. Speakers must keep one hand on the court’s central line, a custom meant to discourage anyone from fleeing a promise."
    },
    {
      "id": "loc_sunward_throat",
      "name": "Sunward Throat",
      "description": "A winding fissure that opens toward the comet’s bright face. Its vents will soon erupt in a hot plume, and the fleet’s captains gather here to test sails, calculate departure windows, and argue over who has the right to leave first."
    }
  ],
  "factions": [
    {
      "id": "fac_braid_guild",
      "name": "The Braid Guild",
      "description": "Keepers of contracts, cargo seals, and market peace. Their factotums are trained to weigh testimony against physical traces, but guild rulings only hold while enough traders agree to honor them.",
      "location_ids": [
        "loc_blue_vault",
        "loc_knotcourt"
      ]
    },
    {
      "id": "fac_sailkin",
      "name": "The Sailkin Caravans",
      "description": "A loose league of family crews who navigate by canvas, tether, and carefully timed reaction plumes. They want the star-map found quickly, though several captains fear it could expose the routes that keep their kin safe.",
      "location_ids": [
        "loc_crown_dock",
        "loc_sunward_throat"
      ]
    },
    {
      "id": "fac_bell_merchants",
      "name": "The Bell Merchants",
      "description": "Dealers who use the Coin Choir’s chimes as a living ledger of reputation and debt. They can reconstruct who crossed the bazaar by sound, yet a false rhythm could ruin their most valuable asset: trust.",
      "location_ids": [
        "loc_coin_choir",
        "loc_crown_dock"
      ]
    },
    {
      "id": "fac_icewardens",
      "name": "The Icewardens",
      "description": "Comet-born tenders who maintain the tunnels and vent markers. They believe no outsider should own a map that charts the comet’s hidden cavities, especially with the burn approaching.",
      "location_ids": [
        "loc_blue_vault",
        "loc_sunward_throat"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_sail_and_plume",
      "statement": "Ships manoeuvre with sails, tethers, and reaction plumes; no energy weapons are used or permitted in the market.",
      "category": "technology"
    },
    {
      "id": "rul_ice_record",
      "statement": "Deep comet ice preserves physical marks and can carry faint echoes, but it cannot reveal who made a mark without corroborating evidence.",
      "category": "physics"
    },
    {
      "id": "rul_tether_oath",
      "statement": "A promise sworn at Knotcourt is binding only when the speaker holds the central line and two independent witnesses answer its chime.",
      "category": "social"
    },
    {
      "id": "rul_burn_window",
      "statement": "As the comet nears the sun, venting ice creates a brief plume-driven departure window; after it passes, the fleet cannot remain safely moored.",
      "category": "physics"
    },
    {
      "id": "rul_map_seal",
      "statement": "A sealed star-map may be opened only by its named custodian or by a guild ruling supported by evidence from two separate locations.",
      "category": "social"
    },
    {
      "id": "rul_chime_ledger",
      "statement": "The Coin Choir’s stall rhythms count as public testimony, but a chime alone cannot establish guilt.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_comet_capture",
      "name": "The First Mooring",
      "description": "A stranded convoy caught the comet with tethers and sailcloth, turning a desperate refuge into a moving harbor. Its first captains agreed that no single crew would own the ice or its routes.",
      "era": "Founding season",
      "location_ids": [
        "loc_crown_dock",
        "loc_sunward_throat"
      ]
    },
    {
      "id": "evt_guild_braid",
      "name": "The Braid Compact",
      "description": "After a cargo feud severed several mooring lines, traders braided their separate contracts into a common code and established the guild tribunal.",
      "era": "Compact years",
      "location_ids": [
        "loc_knotcourt",
        "loc_blue_vault"
      ]
    },
    {
      "id": "evt_choir_ledger",
      "name": "The Night of Many Bells",
      "description": "A fire in the old bazaar destroyed written ledgers. Merchants rebuilt their accounts from stall chimes remembered by neighbors, and the Coin Choir became both marketplace and record.",
      "era": "Ledger winter",
      "location_ids": [
        "loc_coin_choir"
      ]
    },
    {
      "id": "evt_map_sealed",
      "name": "The Map Under Ice",
      "description": "The Icewardens found a route chart in a buried cavity and surrendered it to guild custody under a seal. They insisted its hidden passages remain unknown until the comet’s vents were understood.",
      "era": "Three circuits ago",
      "location_ids": [
        "loc_blue_vault",
        "loc_sunward_throat"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_stolen_map",
      "name": "The Missing Seal",
      "description": "The star-map has vanished from the Blue Vault, and the intact seal suggests either an inside hand or a copy made from a sound impression. The factotum must identify a credible chain of evidence before any faction claims the map or accuses a rival.",
      "faction_ids": [
        "fac_braid_guild",
        "fac_sailkin",
        "fac_icewardens"
      ]
    },
    {
      "id": "cnf_departure_rights",
      "name": "Who Leaves First",
      "description": "The Sailkin want a prompt ruling so their families can prepare to depart, while the Icewardens demand that the map remain closed until the vent paths are secured. Delay may save the secret but cost the fleet its safest window.",
      "faction_ids": [
        "fac_sailkin",
        "fac_icewardens",
        "fac_braid_guild"
      ]
    },
    {
      "id": "cnf_broken_rhythm",
      "name": "The Silent Stall",
      "description": "A merchant’s identifying chime was heard near the vault shortly before the theft, but that merchant claims someone has learned to imitate the Choir. If the testimony is false, the guild risks destroying the trust that keeps the market together.",
      "faction_ids": [
        "fac_bell_merchants",
        "fac_braid_guild"
      ]
    }
  ]
}

