    },
    {
      "id": "rul_burn_window",
      "statement": "As the comet nears the sun, venting ice creates a brief plume-driven departure window; after it passes, the fleet cannot remain safely moored.",
      "category": "physics"
    },
    {
      "id": "rul_map_seal",
      "statement": "A sealed star-map may be opened only by its named custodian or by a guild ruling supported by evidence from two separate locations.",
      "category": "social"
    },
    {
      "id": "rul_chime_ledger",
      "statement": "The Coin Choir’s stall rhythms count as public testimony, but a chime alone cannot establish guilt.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_comet_capture",
      "name": "The First Mooring",
      "description": "A stranded convoy caught the comet with tethers and sailcloth, turning a desperate refuge into a moving harbor. Its first captains agreed that no single crew would own the ice or its routes.",
      "era": "Founding season",
      "location_ids": [
        "loc_crown_dock",
        "loc_sunward_throat"
      ]
    },
    {
      "id": "evt_guild_braid",
      "name": "The Braid Compact",
      "description": "After a cargo feud severed several mooring lines, traders braided their separate contracts into a common code and established the guild tribunal.",
      "era": "Compact years",
      "location_ids": [
        "loc_knotcourt",
        "loc_blue_vault"
      ]
    },
    {
      "id": "evt_choir_ledger",
      "name": "The Night of Many Bells",
      "description": "A fire in the old bazaar destroyed written ledgers. Merchants rebuilt their accounts from stall chimes remembered by neighbors, and the Coin Choir became both marketplace and record.",
      "era": "Ledger winter",
      "location_ids": [
        "loc_coin_choir"
      ]
    },
    {
      "id": "evt_map_sealed",
      "name": "The Map Under Ice",
      "description": "The Icewardens found a route chart in a buried cavity and surrendered it to guild custody under a seal. They insisted its hidden passages remain unknown until the comet’s vents were understood.",
      "era": "Three circuits ago",
      "location_ids": [
        "loc_blue_vault",
        "loc_sunward_throat"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_stolen_map",
      "name": "The Missing Seal",
      "description": "The star-map has vanished from the Blue Vault, and the intact seal suggests either an inside hand or a copy made from a sound impression. The factotum must identify a credible chain of evidence before any faction claims the map or accuses a rival.",
      "faction_ids": [
        "fac_braid_guild",
        "fac_sailkin",
        "fac_icewardens"
      ]
    },
    {
      "id": "cnf_departure_rights",
      "name": "Who Leaves First",
      "description": "The Sailkin want a prompt ruling so their families can prepare to depart, while the Icewardens demand that the map remain closed until the vent paths are secured. Delay may save the secret but cost the fleet its safest window.",
      "faction_ids": [
        "fac_sailkin",
        "fac_icewardens",
        "fac_braid_guild"
      ]
    },
    {
      "id": "cnf_broken_rhythm",
      "name": "The Silent Stall",
      "description": "A merchant’s identifying chime was heard near the vault shortly before the theft, but that merchant claims someone has learned to imitate the Choir. If the testimony is false, the guild risks destroying the trust that keeps the market together.",
      "faction_ids": [
        "fac_bell_merchants",
        "fac_braid_guild"
      ]
    }
  ]
}

response.output:
{
  "world_id": "wld_rainledger_harbor",
  "name": "The Rain-Ledger Harbor",
  "description": "In the sixteenth-century Indian Ocean port of Veyr, the monsoon is both wealth and deadline. Its arrival opens the sea roads west and east; its turning can strand ships, spoil cargo, and end a year of trade. Nalin, a harbor scribe, must reconcile three foreign envoys' rival claims to the first sailing slot before the favorable wind shifts. In a city of wet stone, spice smoke, bright awnings, and watchful clerks, the dispute turns on a local custom: each claim is recorded on palm leaf, then tested against a rain-fed tide gauge whose rising water reveals which vessel truly entered the harbor first. The gauge is old, its marks are worn, and someone has altered the record. Sumptuous ceremony masks a tense contest over evidence, reputation, and the port's right to decide who sails.",
  "locations": [
    {
      "id": "loc_veyr_harbor",
      "name": "Veyr Harbor",
      "description": "A deep, crowded inlet where dhows, stitched-plank ships, and coastal craft wait beneath pennants heavy with rain. A carved stone tide gauge stands beside the customs quay; its channels fill from the monsoon downpour and mark the harbor's changing water."
    },
    {
      "id": "loc_palm_leaf_registry",
      "name": "Palm-Leaf Registry",
      "description": "A shaded counting house above the quay, fragrant with lamp oil and cardamom. Scribes keep cargo tallies and sailing claims on palm leaves, binding each entry with a colored cord witnessed by two people."
    },
    {
      "id": "loc_monsoon_court",
      "name": "Court of the Four Winds",
      "description": "A public pavilion where merchants, pilots, and visiting envoys petition the harbor magistrate. Its painted ceiling shows the seasonal winds, while open arches let rain and sea spray carry every argument to the crowd."
    },
    {
      "id": "loc_lantern_spit",
      "name": "Lantern Spit",
      "description": "A narrow sandbar at the harbor mouth, marked by a stone lantern and a line of mooring posts. Vessels wait here for a pilot's signal; at spring tide, the bar nearly disappears beneath choppy water."
    }
  ],
  "factions": [
    {
      "id": "fac_harbor_registry",
      "name": "Keepers of the Quay",
      "description": "The port's scribes, pilots, and customs officers, charged with keeping the sailing order credible. Their standing depends on proving that local records are fair, even when a powerful visitor challenges them.",
      "location_ids": [
        "loc_palm_leaf_registry",
        "loc_veyr_harbor",
        "loc_lantern_spit"
      ]
    },
    {
      "id": "fac_saffron_envoy",
      "name": "The Saffron Envoy's Company",
      "description": "A wealthy delegation from the western sea, carrying gifts of worked metal and fine cloth. Its envoy insists their ship secured the first slot and fears a missed wind will cost the court that sent them its standing."
      ,"location_ids": [
        "loc_monsoon_court",
        "loc_veyr_harbor"
      ]
    },
    {
      "id": "fac_pearl_envoy",
      "name": "The Pearl Envoy's Company",
      "description": "Merchants and attendants from an island court, whose pearl tribute must reach home before a rival audience. They present a cord-marked claim and suspect the registry favors the largest purse.",
      "location_ids": [
        "loc_monsoon_court",
        "loc_palm_leaf_registry"
      ]
    },
    {
      "id": "fac_copper_envoy",
      "name": "The Copper Envoy's Company",
      "description": "A disciplined delegation from the eastern coast, whose ship carries copper ingots and a sealed treaty. Their envoy claims a pilot gave them the earliest signal and threatens to take the dispute beyond Veyr if they are passed over.",
      "location_ids": [
        "loc_monsoon_court",
        "loc_lantern_spit"
      ]
    },
    {
      "id": "fac_pilot_guild",
      "name": "Guild of the Rain Pilots",
      "description": "Local pilots who know the shifting shoals and the harbor's fickle currents. Their customary signals are spoken and shown by lantern, but no single pilot's testimony is trusted without a second witness.",
      "location_ids": [
        "loc_lantern_spit",
        "loc_veyr_harbor"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_seasonal_winds",
      "statement": "The monsoon governs the safe sailing season; when its wind turns, outward voyages may be delayed for weeks or forced onto dangerous routes.",
      "category": "physics"
    },
    {
      "id": "rul_slot_witnesses",
      "statement": "A sailing claim is valid only when its palm-leaf entry bears two independent witnesses and the harbor clerk's mark.",
      "category": "social"
    },
    {
      "id": "rul_tide_gauge",
      "statement": "For vessels waiting at the harbor mouth, the first sailing slot follows the earliest verified arrival at the stone tide gauge, not rank, cargo value, or order of petition.",
      "category": "social"
    },
    {
      "id": "rul_pilot_signal",
      "statement": "Only a licensed pilot may guide a ship across the shoals, and a departure signal must be acknowledged by lantern from the quay.",
      "category": "technology"
    },
    {
      "id": "rul_no_mechanized_messages",
      "statement": "News travels by sail, runner, signal lantern, or spoken witness; the port has no electrical or mechanized means of distant communication.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_gauge_built",
      "name": "The Gauge After the Great Flood",
      "description": "After floodwater wrecked the old quay, masons cut a rain-fed channel into the harbor stone. The magistrates adopted its marks as a public check on the claims of captains and pilots.",
      "era": "Several generations before the present monsoon",
      "location_ids": [
        "loc_veyr_harbor"
      ]
    },
    {
      "id": "evt_cord_custom",
      "name": "The Witness Cord Accord",
      "description": "A quarrel over a vanished cargo led the registry to bind each palm-leaf claim with a colored cord. Two witnesses must touch the cord before it is sealed, making later substitutions easier to detect.",
      "era": "Recent generations",
      "location_ids": [
        "loc_palm_leaf_registry"
      ]
    },
    {
      "id": "evt_spit_signal",
      "name": "Lanterns at the Bar",
      "description": "When a night squall drove several ships onto the shoals, the pilot guild established a shared lantern signal from the spit. The custom has since made the guild indispensable and its testimony politically sensitive.",
      "era": "A generation ago",
      "location_ids": [
        "loc_lantern_spit"
      ]
    },
    {
      "id": "evt_envoys_arrive",
      "name": "Three Seals Before the Turn",
      "description": "Three envoys reached Veyr within days of one another, each carrying a sealed request for the first sailing slot. Their ships now wait in the harbor as the clouds thicken and the tide gauge's lower marks begin to blur.",
      "era": "The present monsoon",
      "location_ids": [
        "loc_veyr_harbor",
        "loc_monsoon_court",
        "loc_lantern_spit"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_first_sailing",
      "name": "The First Slot",
      "description": "The three envoys each claim the earliest place in the sailing order, but only one ship can leave first. Nalin must decide whether the damaged gauge, disputed witness cords, or pilot testimony can settle the matter before the wind turns.",
      "faction_ids": [
        "fac_saffron_envoy",
        "fac_pearl_envoy",
        "fac_copper_envoy",
        "fac_harbor_registry",
        "fac_pilot_guild"
      ]
    },
    {
      "id": "cnf_registry_trust",
      "name": "A Record Under Suspicion",
      "description": "A mark on the tide record appears to have been changed after the rain began. The registry risks losing its authority if it hides the alteration, while an open inquiry could expose a clerk or witness to pressure from the envoys.",
      "faction_ids": [
        "fac_harbor_registry",
        "fac_saffron_envoy",
        "fac_pearl_envoy",
        "fac_copper_envoy"
      ]
    }
  ]
}

