{
  "world_id": "wld_ashfen_parish",
  "name": "The Ashfen Vigil",
  "description": "Ashfen is a remote moor parish of peat tracks, rain-black stone, and scattered homes, where every wall lantern is tended by hand. The parish keeps a record of each night its lamps have burned, but a page from last winter's ledger has been cut away. Its new lamplighter discovers that the lights are more than a comfort: if every parish lantern goes dark on one night, something beneath the drowned ground can find its way to the living. In this folk-horror world, custom is both shelter and snare, and the people who guard the old practice disagree about what the missing record concealed.",
  "locations": [
    {
      "id": "loc_ashfen_green",
      "name": "Ashfen Green",
      "description": "A wind-scoured patch of common ground where the parish paths meet. Its central wall lantern is the first to be lit at dusk and the last to be checked before dawn."
    },
    {
      "id": "loc_wickhouse",
      "name": "The Wickhouse",
      "description": "A low stone shed beside the green, stocked with oil, trimmed wicks, and the parish's bound ledgers. Soot marks on its rafters form a tally no keeper admits to making."
    },
    {
      "id": "loc_drowned_mile",
      "name": "Drowned Mile",
      "description": "A half-sunken causeway across the moor, lined with leaning wall lanterns. The peat here gives back old sounds, sometimes in the voices of people still alive."
    },
    {
      "id": "loc_bellwether",
      "name": "Bellwether Croft",
      "description": "A lonely croft on a rise above the parish, where the oldest lamp-keeper lives among sheep bells and rain barrels. From its upper window, every parish light can be seen except one."
    }
  ],
  "factions": [
    {
      "id": "fac_lampwardens",
      "name": "The Lampwardens",
      "description": "A hereditary circle of keepers who tend the wall lanterns and preserve the nightly ledger. They insist the routine must never be altered, though their oldest members know the record has been edited before.",
      "location_ids": [
        "loc_ashfen_green",
        "loc_wickhouse",
        "loc_drowned_mile"
      ]
    },
    {
      "id": "fac_moorholders",
      "name": "The Moorholders",
      "description": "Families whose grazing rights depend on the old paths and who resent the labor and oil demanded by the vigil. Some quietly let lamps gutter, hoping to prove the custom has outlived its purpose.",
      "location_ids": [
        "loc_drowned_mile",
        "loc_bellwether"
      ]
    },
    {
      "id": "fac_bellwether_house",
      "name": "Bellwether House",
      "description": "The household of the last retired keeper, bound to the parish by an oath no one will explain plainly. They protect a private list of names that does not appear in the official ledger.",
      "location_ids": [
        "loc_bellwether",
        "loc_wickhouse"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_lastlight",
      "statement": "At least one parish wall lantern must remain alight through every night; when all are dark together, the drowned ground can reach the living.",
      "category": "metaphysics"
    },
    {
      "id": "rul_handtended",
      "statement": "A wall lantern's flame must be lit and tended by hand; no machine in Ashfen can keep the vigil.",
      "category": "technology"
    },
    {
      "id": "rul_ledger_marks",
      "statement": "The ledger records which lanterns burned, but a name written in its margin is never spoken aloud before sunrise.",
      "category": "social"
    },
    {
      "id": "rul_moor_echo",
      "statement": "Across the Drowned Mile, a voice heard after dusk may answer a question asked earlier that day, though no speaker is visible.",
      "category": "metaphysics"
    }
  ],
  "history": [
    {
      "id": "evt_first_vigil",
      "name": "The First Vigil",
      "description": "After a winter flood uncovered a row of old stones beneath the moor, the parish began keeping a lamp burning at the green. The custom spread to every wall along the paths.",
      "era": "Before the parish books",
      "location_ids": [
        "loc_ashfen_green",
        "loc_drowned_mile"
      ]
    },
    {
      "id": "evt_winter_names",
      "name": "The Winter of Borrowed Names",
      "description": "A generation ago, several households reported hearing familiar voices from the Drowned Mile. The Lampwardens added a rule against speaking ledger-margin names before sunrise, then sealed that winter's account.",
      "era": "A generation ago",
      "location_ids": [
        "loc_drowned_mile",
        "loc_wickhouse"
      ]
    },
    {
      "id": "evt_cut_leaf",
      "name": "The Missing Leaf",
      "description": "Last winter, a page was cut from the ledger. The remaining entries show every lantern alight on each recorded night, but the binding holds a narrow strip of paper bearing a list of names.",
      "era": "Last winter",
      "location_ids": [
        "loc_wickhouse"
      ]
    },
    {
      "id": "evt_new_keeper",
      "name": "A New Keeper Arrives",
      "description": "The new lamplighter takes up the rounds and notices that the lantern visible from Bellwether Croft has no entry beside it on several nights. The retired keeper refuses to explain the omission.",
      "era": "Present",
      "location_ids": [
        "loc_bellwether",
        "loc_ashfen_green"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_vigil_or_proof",
      "name": "Vigil or Proof",
      "description": "The Lampwardens demand that every light be kept burning, while the Moorholders want one deliberate dark night to test whether the danger is real. The new keeper must decide whether to preserve the routine or risk exposing its purpose.",
      "faction_ids": [
        "fac_lampwardens",
        "fac_moorholders"
      ]
    },
    {
      "id": "cnf_names_in_margin",
      "name": "Names in the Margin",
      "description": "Bellwether House guards the private list that may explain the missing leaf, while the Lampwardens fear that revealing it will undo the vigil. The list may identify those the lights have protected—or those they have kept below.",
      "faction_ids": [
        "fac_lampwardens",
        "fac_bellwether_house"
      ]
    }
  ]
}

